// Input 0 = config, Input 1+ = executions (main + subflows)
const config = $item(0).$node["Configuration"].json;
const executions = items.slice(1).map(i => i.json);

// === Secret & sensitive patterns ===
const secretRegexes = [
  { regex: /\bBearer\s+[A-Za-z0-9\.\-_]+/, severity: "high", desc: "Bearer token" },
  { regex: /\bsk-[A-Za-z0-9]{20,64}/, severity: "high", desc: "OpenAI API key" },
  { regex: /\bAKIA[0-9A-Z]{16}\b/, severity: "high", desc: "AWS Access Key" },
  { regex: /AIza[0-9A-Za-z\-_]{35}/, severity: "high", desc: "Google API key" },
  { regex: /xox[baprs]-[0-9A-Za-z-]{10,}/, severity: "high", desc: "Slack token" },
  { regex: /sk_live_[0-9a-zA-Z]{24}/, severity: "high", desc: "Stripe live key" },
  { regex: /eyJ[a-zA-Z0-9\-_]{10,}\.[a-zA-Z0-9\-_]{10,}\.[a-zA-Z0-9\-_]{10,}/, severity: "high", desc: "JWT token" },
  { regex: /([A-Za-z0-9+\/]{40,}={0,2})/, severity: "medium", desc: "Base64-like secret" },
  { regex: /(api[_-]?key)/i, severity: "high", desc: "API Key keyword" },
  { regex: /(access[_-]?token)/i, severity: "high", desc: "Access token keyword" },
  { regex: /(secret|password)/i, severity: "high", desc: "Secret/password keyword" },
  { regex: /\b(admin|root|test(user)?\d*)\b/i, severity: "high", desc: "Common username" },
  { regex: /\b(password|123456|qwerty|letmein|admin123|password123)\b/i, severity: "high", desc: "Weak password" },
  { regex: /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i, severity: "medium", desc: "Hardcoded email address" },
  { regex: /(auth(entication)?|authorization)/i, severity: "low", desc: "Auth keyword" },
  { regex: /\b[0-9a-zA-Z_-]{20,64}\b/, severity: "medium", desc: "Suspicious long string" },
];

// === Company identifiers from config ===
let companyPatterns = [];
if (config.companyIdentifiers) {
  const companies = Array.isArray(config.companyIdentifiers)
    ? config.companyIdentifiers
    : String(config.companyIdentifiers).split(",").map(s => s.trim());
  companyPatterns = companies.map(c => ({
    regex: new RegExp(`\\b${c}\\b`, "i"),
    severity: "low",
    desc: "Company identifier"
  }));
}

// === Whitelist patterns ===
const whitelistPatterns = [
  /^app[a-zA-Z0-9]{14}$/i,
  /^tbl[a-zA-Z0-9]{14}$/i,
  /^[a-zA-Z0-9_-]{25,}$/i,
  /^asst_[a-zA-Z0-9]{20,}$/i,
  /^oAuth2$/i,
  /^predefinedCredentialType$/i,
];

function isWhitelisted(val) {
  return whitelistPatterns.some(p => p.test(val));
}

function flattenParams(obj, prefix = "") {
  let results = [];
  for (const [key, val] of Object.entries(obj || {})) {
    const fullKey = prefix ? `${prefix}.${key}` : key;
    if (val && typeof val === "object") {
      results = results.concat(flattenParams(val, fullKey));
    } else if (val !== undefined && val !== null) {
      results.push({ key: fullKey, value: String(val) });
    }
  }
  return results;
}

function classifyCredential(node) {
  if (!node.credentials || Object.keys(node.credentials).length === 0) return "hardcoded";
  if (node.parameters?.authentication) {
    const auth = node.parameters.authentication.toLowerCase();
    if (auth.includes("oauth")) return "external";
    if (auth.includes("generic")) return "generic";
    if (auth.includes("predefined")) return "predefined";
  }
  return "predefined";
}

// === Security audit per workflow ===
function auditWorkflow(exec, label) {
  const wf = exec.workflowData || exec.data?.resultData?.workflowData;
  const wfName = wf?.name || label || "Unnamed Workflow";
  const wfId = exec.workflowId || "unknown";

  const nodes = wf?.nodes || [];
  const flagged = [];
  const apiNodes = [];

  nodes.forEach(node => {
    const nodeInfo = { node: node.name, type: node.type };
    const params = flattenParams(node.parameters);

    if (/httpRequest|api|google|slack|airtable|openAi/i.test(node.type)) {
      apiNodes.push({
        node: node.name,
        type: node.type,
        credentialType: classifyCredential(node),
      });
    }

    for (const { key, value } of params) {
      if (value.length > 5000) continue;
      for (const { regex, severity, desc } of [...secretRegexes, ...companyPatterns]) {
        if (regex.test(value) && !isWhitelisted(value)) {
          flagged.push({
            ...nodeInfo,
            key,
            value: value.slice(0, 100),
            issue: desc,
            severity,
          });
        }
      }
    }
  });

  return {
    workflowLabel: label + ` (${wfName})`,
    workflowId: wfId,
    workflowName: wfName,
    issuesFound: flagged.length,
    severityCount: {
      high: flagged.filter(f => f.severity === "high").length,
      medium: flagged.filter(f => f.severity === "medium").length,
      low: flagged.filter(f => f.severity === "low").length,
    },
    apiNodes,
    flagged,
  };
}

// === Group executions by workflowId ===
const grouped = executions.reduce((acc, exec) => {
  const wfid = exec.workflowId || "unknown";
  if (!acc[wfid]) acc[wfid] = [];
  acc[wfid].push(exec);
  return acc;
}, {});

// Grab mainId explicitly from "Get Latest Successful Executions of Workflow"
let mainId;
try {
  const mainNode = $('Get Latest Successful Executions of Workflow').first();
  mainId = mainNode?.json?.workflowId;
} catch (e) {
  mainId = executions[0]?.workflowId || "unknown";
}

const audits = [];
for (const [wfid, execs] of Object.entries(grouped)) {
  const label = wfid === mainId ? "Main Workflow" : "Subflow";
  audits.push(auditWorkflow(execs[0], label));
}

// === Always put main workflow first ===
const ordered = audits.sort((a, b) => {
  if (a.workflowId === mainId) return -1;
  if (b.workflowId === mainId) return 1;
  return 0;
});

return ordered.map(a => ({ json: a }));

// Input 0 = config, Input 1+ = executions (main + subflows)
const config = $item(0).$node["Configuration"].json;
const executions = items.map(i => i.json);

function stats(values) {
  if (!values.length) return { mean: 0, variance: 0, stdev: 0 };
  const mean = values.reduce((a, b) => a + b, 0) / values.length;
  const variance = values.reduce((a, b) => a + (b - mean) ** 2, 0) / values.length;
  const stdev = Math.sqrt(variance);
  return { mean: Math.round(mean), variance: Math.round(variance), stdev: Math.round(stdev) };
}

function grade(avg, stdev, globalAvg, samples) {
  if (avg < 50) return "✅ stable (ignored <50ms)";
  if (samples < 3) return "✅ stable (low sample)";
  if (avg > globalAvg * Number(config.bottleneckThreshold)) return "🔴 bottleneck";
  if (stdev > avg * Number(config.unstableThreshold)) return "⚠️ unstable";
  return "✅ stable";
}

// === Audit function ===
function auditWorkflow(execs, label, workflowId, workflowName) {
  let totalWorkflowTime = 0;
  let workflowCount = 0;
  const nodeTimes = {};
  const seenNodes = new Set();

  // Pull nodes from either exec.workflowData or exec.data.resultData.workflowData
  const wfNodes =
    execs[0]?.workflowData?.nodes ||
    execs[0]?.data?.resultData?.workflowData?.nodes ||
    [];

  const wfNodeNames = wfNodes.map(n => n.name);

  // Track disabled nodes explicitly
  const disabledNodes = wfNodes
    .filter(n => n.disabled === true)
    .map(n => n.name);

  execs.slice(0, Number(config.maxExecutions)).forEach(exec => {
    const runData = exec.data?.resultData?.runData || {};
    const subExecs = exec.data?.resultData?.subExecutions || [];

    subExecs.forEach(sub => {
      const subRunData = sub.data?.resultData?.runData || {};
      for (const [nodeName, nodeRuns] of Object.entries(subRunData)) {
        nodeRuns.forEach(e => {
          const t = e.executionTime || 0;
          thisWorkflowTime += t;

          if (!nodeTimes[nodeName]) nodeTimes[nodeName] = [];
          nodeTimes[nodeName].push(t);
          seenNodes.add(nodeName);
        });
      }
    });


    let thisWorkflowTime = 0;

    for (const [nodeName, nodeRuns] of Object.entries(runData)) {
      nodeRuns.forEach(e => {
        const t = e.executionTime || 0;
        thisWorkflowTime += t;

        if (!nodeTimes[nodeName]) nodeTimes[nodeName] = [];
        nodeTimes[nodeName].push(t);
        seenNodes.add(nodeName);
      });
    }

    totalWorkflowTime += thisWorkflowTime;
    workflowCount++;
  });

  const avgWorkflowTime =
    workflowCount > 0 ? Math.round(totalWorkflowTime / workflowCount) : 0;

  const nodeStats = Object.entries(nodeTimes).map(([node, times]) => {
    const { mean, variance, stdev } = stats(times);
    return {
      node,
      avgExecutionTime: mean,
      variance,
      stdev,
      samples: times.length,
      performanceGrade: grade(mean, stdev, avgWorkflowTime, times.length),
      dominantShare:
        avgWorkflowTime > 0
          ? ((mean / avgWorkflowTime) * 100).toFixed(1) + "%"
          : "0%",
    };
  });

  const slowestNodes = [...nodeStats]
    .sort((a, b) => b.avgExecutionTime - a.avgExecutionTime)
    .slice(0, 3);

  const mostUnstableNodes = [...nodeStats]
    .filter(n => n.avgExecutionTime >= 50)
    .sort((a, b) => b.stdev - a.stdev)
    .slice(0, 3);

  // Nodes that are not disabled but also never executed
  const neverExecutedNodes = wfNodeNames.filter(
    n => !seenNodes.has(n) && !disabledNodes.includes(n)
  );

  return {
    workflowLabel: label,
    workflowName,
    workflowId,
    executionsAnalysed: workflowCount,
    avgWorkflowTime,
    slowestNodes,
    mostUnstableNodes,
    disabledNodes,
    disabledNodesCount: disabledNodes.length,
    neverExecutedNodes,
    neverExecutedNodesCount: neverExecutedNodes.length,
    nodeStats,
  };
}

// === Grab workflowIds and names from upstream nodes safely ===
let mainId, mainName, subId, subName;

try {
  const mainNode = $('Get Latest Successful Executions of Workflow').first();
  mainId = mainNode?.json?.workflowId;
  mainName = mainNode?.json?.workflowData?.name || "Unnamed Main Workflow";
} catch (e) {
  mainId = "unknown";
  mainName = "Unnamed Main Workflow";
}

try {
  const subNode = $('Get Latest Successful Executions of Subworkflows').first();
  subId = subNode?.json?.workflowId;
  subName = subNode?.json?.workflowData?.name || "Unnamed Subflow";
} catch (e) {
  subId = null;
  subName = null;
}

// === Group executions by workflowId ===
const grouped = executions.reduce((acc, exec) => {
  const wfid = exec.workflowId || "unknown";
  if (!acc[wfid]) acc[wfid] = [];
  acc[wfid].push(exec);
  return acc;
}, {});

const audits = [];

for (const [wfid, execs] of Object.entries(grouped)) {
  let wfName = "Unnamed Workflow";

  if (wfid === mainId) {
    wfName = mainName;
  } else if (subId && wfid === subId) {
    wfName = subName;
  }

  const label =
    wfid === mainId ? `Main Workflow (${wfName})` : `Subflow (${wfName})`;

  audits.push(auditWorkflow(execs, label, wfid, wfName));
}

// === Put main workflow first ===
const ordered = audits.sort((a, b) => {
  if (a.workflowId === mainId) return -1;
  if (b.workflowId === mainId) return 1;
  return 0;
});

// Return
return ordered.map(a => ({ json: a }));

const subflows = [];

items.forEach(item => {
  const runData = item.json.data?.resultData?.runData || {};
  for (const [nodeName, nodeRuns] of Object.entries(runData)) {
    nodeRuns.forEach(e => {
      const subExec = e?.metadata?.subExecution;
      if (subExec?.workflowId) {
        subflows.push({
          json: {
            workflowId: subExec.workflowId,
            executionId: subExec.executionId, // you can use this if you want that exact run
            parentWorkflowId: item.json.workflowId,
            parentNode: nodeName
          }
        });
      }
    });
  }
});

return subflows;

// Input = aggregated results from performance + security + AI audits
const config = $item(0).$node["Configuration"].json;

// Aggregate packs everything under one item -> .json.data
const audits = items[0].json.data;

function buildScriptedReport(audits) {
  let lines = [];
  lines.push("# Workflow Audit Report");
  lines.push("");
  lines.push("## Glossary");
  lines.push("- **Identifiers**: Sensitive company-specific data (flagged if present).");
  lines.push("- **Disabled nodes**: Nodes that exist in the workflow but are not executed.");
  lines.push("- **Never-executed nodes**: Nodes that are present but never triggered in analysed runs.");
  lines.push("- **Potential bottleneck**: A node with significantly higher average execution time than others.");
  lines.push("- **AI nodes**: Any workflow nodes calling an LLM or AI model.");
  lines.push("- **Error handling** → Potentially risky nodes and how to mitigate failures.");
  lines.push("- **Unclear node names**: Nodes left with defaults like `Node1` or very short names.");
  lines.push("");

  // === Global stats ===
  const totalIssues = audits.reduce(
    (acc, a) => {
      acc.high += a.severityCount?.high ?? 0;
      acc.medium += a.severityCount?.medium ?? 0;
      acc.low += a.severityCount?.low ?? 0;
      return acc;
    },
    { high: 0, medium: 0, low: 0 }
  );

  const uniqueWfs = [
    ...new Set(audits.map(a => a.workflowId).filter(id => id !== "ALL"))
  ];

  lines.push("## Global Summary");
  lines.push(`- **Total workflows analysed:** ${uniqueWfs.length}`);
  lines.push(`- **Total issues by severity:** 🔴 High: ${totalIssues.high} / 🟠 Medium: ${totalIssues.medium} / 🟢 Low: ${totalIssues.low}`);
  lines.push("");

  // === Group audits by workflowId ===
  const grouped = {};
  for (const a of audits) {
    if (!grouped[a.workflowId]) {
      grouped[a.workflowId] = {
        workflowLabel: a.workflowLabel,
        workflowId: a.workflowId,
        executionsAnalysed: null,
        avgWorkflowTime: null,
        issuesFound: 0,
        severityCount: { high: 0, medium: 0, low: 0 },
        flagged: [],
        slowestNodes: [],
        disabledNodes: [],
        neverExecutedNodes: [],
        apiNodes: [],
        aiNodes: [],
        errorNodes: [],
        unclearNodeNames: [],      // NEW
        recommendations: []
      };
    }

    if (a.executionsAnalysed && a.executionsAnalysed !== "n/a") {
      grouped[a.workflowId].executionsAnalysed = a.executionsAnalysed;
    }
    if (a.avgWorkflowTime && a.avgWorkflowTime !== "n/a") {
      grouped[a.workflowId].avgWorkflowTime = a.avgWorkflowTime;
    }

    grouped[a.workflowId].issuesFound += a.issuesFound ?? 0;
    grouped[a.workflowId].severityCount.high += a.severityCount?.high ?? 0;
    grouped[a.workflowId].severityCount.medium += a.severityCount?.medium ?? 0;
    grouped[a.workflowId].severityCount.low += a.severityCount?.low ?? 0;

    if (a.flagged?.length) grouped[a.workflowId].flagged.push(...a.flagged);
    if (a.slowestNodes?.length) grouped[a.workflowId].slowestNodes.push(...a.slowestNodes);
    if (a.disabledNodes?.length) grouped[a.workflowId].disabledNodes.push(...a.disabledNodes);
    if (a.neverExecutedNodes?.length) grouped[a.workflowId].neverExecutedNodes.push(...a.neverExecutedNodes);
    if (a.apiNodes?.length) grouped[a.workflowId].apiNodes.push(...a.apiNodes);
    if (a.aiNodes?.length) grouped[a.workflowId].aiNodes.push(...a.aiNodes);
    if (a.errorNodes?.length) grouped[a.workflowId].errorNodes.push(...a.errorNodes);
    if (a.unclearNodeNames?.length) grouped[a.workflowId].unclearNodeNames.push(...a.unclearNodeNames); // NEW
    if (a.recommendations?.length) grouped[a.workflowId].recommendations.push(...a.recommendations);
  }

  // === Per-workflow breakdown ===
  for (const wf of Object.values(grouped)) {
    lines.push(`## ${wf.workflowLabel}`);
    lines.push("");
    lines.push("### Workflow Overview");
    lines.push(`- Workflow ID: ${wf.workflowId}`);
    lines.push(`- Executions analysed: ${wf.executionsAnalysed ?? "n/a"}`);
    lines.push(`- Average runtime: ${wf.avgWorkflowTime ?? "n/a"} ms`);
    lines.push("");

    // === Issue summary
    lines.push("### Issue Summary");
    lines.push("| Severity | Count |");
    lines.push("|----------|-------|");
    lines.push(`| 🔴 High  | ${wf.severityCount.high} |`);
    lines.push(`| 🟠 Medium| ${wf.severityCount.medium} |`);
    lines.push(`| 🟢 Low   | ${wf.severityCount.low} |`);
    lines.push("");

    // === Security Findings
    lines.push("### Security Findings");
    if (wf.flagged.length) {
      lines.push("| Node | Issue | Severity |");
      lines.push("|------|-------|----------|");
      wf.flagged.forEach(f => {
        lines.push(`| ${f.node} | ${f.issue} | ${f.severity} |`);
      });
    } else {
      lines.push("*No security issues detected.*");
    }
    lines.push("");

    // === Performance Findings
    lines.push("### Performance Findings");
    if (wf.slowestNodes.length) {
      lines.push("#### Slowest Nodes");
      lines.push("| Node | Avg Execution Time (ms) |");
      lines.push("|------|--------------------------|");
      wf.slowestNodes.forEach(n =>
        lines.push(`| ${n.node} | ${n.avgExecutionTime} |`)
      );
    } else {
      lines.push("*No performance findings.*");
    }
    lines.push("");

    if (wf.disabledNodes.length || wf.neverExecutedNodes.length) {
      lines.push("#### Disabled & Never Executed Nodes");
      lines.push("| Node | Status |");
      lines.push("|------|--------|");
      wf.disabledNodes.forEach(n => lines.push(`| ${n} | Disabled |`));
      wf.neverExecutedNodes.forEach(n => lines.push(`| ${n} | Never Executed |`));
    } else {
      lines.push("*No disabled or never-executed nodes.*");
    }
    lines.push("");

    // === API & Credential Usage
    lines.push("### API & Credential Usage");
    if (wf.apiNodes.length) {
      lines.push("| Node | Type | Credential Type |");
      lines.push("|------|------|-----------------|");
      wf.apiNodes.forEach(api =>
        lines.push(`| ${api.node} | ${api.type} | ${api.credentialType} |`)
      );
    } else {
      lines.push("*No API nodes detected.*");
    }
    lines.push("");

    // === AI Audit Findings
    lines.push("### AI Audit Findings");
    if (wf.aiNodes.length) {
      lines.push("| Node Name | Node Type | Model | Disabled | Preview | Token Estimate | Avg Execution Time (ms) |");
      lines.push("|-----------|-----------|-------|----------|---------|----------------|--------------------------|");
      wf.aiNodes.forEach(ai =>
        lines.push(`| ${ai.nodeName} | ${ai.nodeType} | ${ai.model ?? "unknown-model"} | ${ai.disabled} | ${ai.preview || ""} | ${ai.tokenEstimate} | ${ai.avgExecutionTime ?? 0} |`)
      );
      lines.push("");
      lines.push(`- Total AI nodes: ${wf.aiNodes.length}`);
      lines.push(`- Active AI nodes: ${wf.aiNodes.filter(n => !n.disabled).length}`);
      lines.push(`- Disabled AI nodes: ${wf.aiNodes.filter(n => n.disabled).length}`);
      lines.push(`- Estimated total tokens: ${wf.aiNodes.reduce((sum, n) => sum + (n.tokenEstimate ?? 0), 0)}`);
    } else {
      lines.push("*No AI usage detected.*");
    }
    lines.push("");

    // === Node Naming
    lines.push("### Node Naming");
    if (wf.unclearNodeNames.length) {
      lines.push("| Node | Issue |");
      lines.push("|------|-------|");
      wf.unclearNodeNames.forEach(n =>
        lines.push(`| ${n} | Unclear or generic name — consider renaming for clarity |`)
      );
    } else {
      lines.push("*All nodes have clear, descriptive names.*");
    }
    lines.push("");

    // === Error Handling
    lines.push("### Error Handling Findings");
    if (wf.errorNodes?.length) {
      const uniqueErrors = [];
      const seen = new Set();
      wf.errorNodes.forEach(e => {
        const key = `${e.node}|${e.errorType}`;
        if (!seen.has(key)) {
          seen.add(key);
          uniqueErrors.push(e);
        }
      });
      if (uniqueErrors.length) {
        lines.push("| Node | Potential Risk | Type | Recommendation |");
        lines.push("|------|----------------|------|----------------|");
        uniqueErrors.forEach(e =>
          lines.push(`| ${e.node} | ${e.error} | ${e.errorType} | ${e.recommendation} |`)
        );
        lines.push("");
      }
    } else {
      lines.push("*No risky nodes detected.*");
    }

    // Always show golden rules
    if (wf.globalRecommendations?.length) {
      lines.push("#### Global Best Practices");
      wf.globalRecommendations.forEach(r => lines.push(`- ${r}`));
    }

    // === Recommendations
    lines.push("### Recommendations");
    if (wf.flagged.length) lines.push("- Review flagged nodes for potential security risks and apply hardening where needed.");
    if (wf.slowestNodes.length) lines.push("- Optimise or refactor slow nodes to reduce execution time.");
    if (wf.disabledNodes.length) lines.push("- Validate whether disabled nodes are still required; remove unused ones.");
    if (wf.neverExecutedNodes.length) lines.push("- Investigate why certain nodes never execute and confirm they are correctly configured.");
    if (wf.aiNodes.length) lines.push("- Monitor AI node usage, token consumption, and prompt length to prevent excessive costs or instability.");
    if (wf.unclearNodeNames.length) lines.push("- Rename unclear or default nodes for better maintainability.");
    if (
      !wf.flagged.length &&
      !wf.slowestNodes.length &&
      !wf.disabledNodes.length &&
      !wf.neverExecutedNodes.length &&
      !wf.aiNodes.length &&
      !wf.unclearNodeNames.length
    ) {
      lines.push("- No major issues detected. Workflow appears stable.");
    }
    lines.push("");
  }

  // === Quick Checklist
  lines.push("## Quick Checklist");
  const check = (cond, label) => cond ? `✅ ${label}` : `⚠️ ${label}`;
  lines.push("- " + check(!audits.some(a => a.flagged?.length), "No security issues"));
  lines.push("- " + check(!audits.some(a => a.slowestNodes?.length), "No performance bottlenecks"));
  lines.push("- " + check(!audits.some(a => a.disabledNodes?.length || a.neverExecutedNodes?.length), "No disabled or never-executed nodes"));
  lines.push("- " + check(!audits.some(a => a.apiNodes?.some(api => api.credentialType === "hardcoded")), "Credentials properly configured"));
  lines.push("- " + check(!audits.some(a => a.aiNodes?.length), "AI usage monitored & controlled"));
  lines.push("- " + check(!audits.some(a => a.unclearNodeNames?.length), "Nodes have clear names"));
  lines.push("");

  // === Overall Recommendations
  lines.push("## Overall Recommendations");
  if (audits.some(a => a.flagged?.length)) lines.push("- Address security issues across workflows with priority.");
  if (audits.some(a => a.slowestNodes?.length)) lines.push("- Focus on performance bottlenecks to improve efficiency.");
  if (audits.some(a => a.disabledNodes?.length)) lines.push("- Review disabled nodes for potential cleanup.");
  if (audits.some(a => a.neverExecutedNodes?.length)) lines.push("- Investigate never-executed nodes for misconfiguration or redundancy.");
  if (audits.some(a => a.aiNodes?.length)) lines.push("- Track AI node usage across workflows and review prompt/token design for cost-effectiveness.");
  if (audits.some(a => a.unclearNodeNames?.length)) lines.push("- Improve workflow maintainability by renaming unclear node labels.");
  if (
    !audits.some(a => a.flagged?.length || a.slowestNodes?.length || a.disabledNodes?.length ||
                      a.neverExecutedNodes?.length || a.aiNodes?.length || a.unclearNodeNames?.length)
  ) {
    lines.push("- No significant risks identified. Current workflows are operating as expected.");
  }

  return lines.join("\n");
}

