import base64
import re

report_md = _input.item.json.get("report") or "# Empty Report"
lines = report_md.splitlines()

# --- PDF constants ---
PAGE_W, PAGE_H = 595, 842
MARGIN_L, MARGIN_T = 50, 50
LINE_SPACING = 14
MAX_TEXT_WIDTH = PAGE_W - 2 * MARGIN_L

def escape_text(s: str) -> str:
    return (s or "").replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")

# crude word wrap (approximate width per char = 0.5*font_size)
def wrap_text(text, size, max_width=MAX_TEXT_WIDTH):
    max_chars = int(max_width / (size * 0.5))
    words = text.split()
    lines, cur = [], ""
    for w in words:
        if len(cur) + len(w) + 1 <= max_chars:
            cur = (cur + " " + w).strip()
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines

# --- Parse Markdown-ish input ---
styled = []
for ln in lines:
    if ln.startswith("### "):
        styled.append(("h3", 12, ln[4:]))
    elif ln.startswith("## "):
        styled.append(("h2", 14, ln[3:]))
    elif ln.startswith("# "):
        styled.append(("h1", 18, ln[2:]))
    elif ln.startswith("- "):
        styled.append(("bullet", 11, ln[2:]))  # keep bullet text
    elif "|" in ln:  # ASCII table
        styled.append(("table", 10, ln))
    else:
        styled.append(("text", 11, ln))

# paginate
lines_per_page = int((PAGE_H - 2*MARGIN_T) // LINE_SPACING)
pages = [styled[i:i+lines_per_page] for i in range(0, len(styled), lines_per_page)] or [[]]

objects = []
def add_object(content: str) -> int:
    objects.append(content)
    return len(objects)

# Fonts
font_regular = add_object("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>")
font_bold    = add_object("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>")
font_mono    = add_object("<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>")

# Helper: render inline text with **bold**
def render_inline(text, font_alias_regular, font_alias_bold, size):
    parts = re.split(r"(\*\*.*?\*\*)", text)
    cmds = []
    for part in parts:
        if part.startswith("**") and part.endswith("**"):
            inner = part[2:-2]
            cmds.append(f"/{font_alias_bold} {size} Tf ({escape_text(inner)}) Tj")
        elif part:
            cmds.append(f"/{font_alias_regular} {size} Tf ({escape_text(part)}) Tj")
    return cmds

# Pages
page_obj_nums = []
for page in pages:
    y = PAGE_H - MARGIN_T
    content = ["BT", f"1 0 0 1 {MARGIN_L} {y} Tm"]
    first_line = True

    for kind, size, text in page:
        font = font_regular
        rgb = "0 0 0 RG"

        if kind == "h1":
            font = font_bold; size = 18; rgb = "0 0 0.8 RG"
        elif kind == "h2":
            font = font_bold; size = 14; rgb = "0.2 0.2 0.2 RG"
        elif kind == "h3":
            font = font_bold; size = 12
        elif kind == "bullet":
            font = font_regular
        elif kind == "table":
            font = font_mono; size = 10

        font_alias = "F1" if font == font_regular else ("F2" if font == font_bold else "F3")

        # spacing
        if not first_line:
            if kind.startswith("h"):
                content.append(f"0 -{LINE_SPACING*1.6} Td")
            else:
                content.append(f"0 -{LINE_SPACING} Td")
        first_line = False

        # wrap long lines
        wrapped_lines = wrap_text(text, size, MAX_TEXT_WIDTH)

        if kind == "bullet":
            for i, line in enumerate(wrapped_lines):
                if i > 0:
                    content.append(f"0 -{LINE_SPACING} Td")
                content.append("20 0 Td")  # indent
                content.append(f"{rgb}")
                content += render_inline("- " + line, "F1", "F2", size)  # ASCII-safe dash
                content.append("-20 0 Td")  # reset indent
        elif kind == "table":
            for i, line in enumerate(wrapped_lines):
                if i > 0:
                    content.append(f"0 -{LINE_SPACING} Td")
                content.append(f"{rgb} /F3 {size} Tf ({escape_text(line)}) Tj")
        else:
            for i, line in enumerate(wrapped_lines):
                if i > 0:
                    content.append(f"0 -{LINE_SPACING} Td")
                content.append(f"{rgb}")
                content += render_inline(line, "F1", "F2", size)

    content.append("ET")

    stream_data = "\n".join(content).encode("latin-1", "replace")
    stream = f"<< /Length {len(stream_data)} >>\nstream\n".encode("latin-1") + stream_data + b"\nendstream"
    contents_obj_num = add_object(stream.decode("latin-1", "ignore"))
    page_obj = (
        f"<< /Type /Page /Parent 0 0 R /MediaBox [0 0 {PAGE_W} {PAGE_H}] "
        f"/Resources << /Font << /F1 {font_regular} 0 R /F2 {font_bold} 0 R /F3 {font_mono} 0 R >> >> "
        f"/Contents {contents_obj_num} 0 R >>"
    )
    page_obj_num = add_object(page_obj)
    page_obj_nums.append(page_obj_num)

# Pages tree
kids_ref = " ".join(f"{n} 0 R" for n in page_obj_nums)
pages_obj_num = add_object(f"<< /Type /Pages /Kids [ {kids_ref} ] /Count {len(page_obj_nums)} >>")

# Fix parent refs
patched = []
for i, obj in enumerate(objects, start=1):
    if i in page_obj_nums:
        obj = obj.replace("/Parent 0 0 R", f"/Parent {pages_obj_num} 0 R")
    patched.append(obj)
objects = patched

# Catalog
catalog_obj_num = add_object(f"<< /Type /Catalog /Pages {pages_obj_num} 0 R >>")

# Assemble PDF
entries = [f"{i} 0 obj\n{obj}\nendobj\n" for i, obj in enumerate(objects, start=1)]
body = "%PDF-1.4\n" + "".join(entries)
cursor = len("%PDF-1.4\n".encode("latin-1"))
offsets = []
for i, obj in enumerate(objects, start=1):
    offsets.append(cursor)
    ent = f"{i} 0 obj\n{objects[i-1]}\nendobj\n"
    cursor += len(ent.encode("latin-1"))

xref_start = len(body.encode("latin-1"))
xref = ["xref", f"0 {len(objects)+1}", "0000000000 65535 f "]
for off in offsets:
    xref.append(f"{off:010d} 00000 n ")

trailer = f"""trailer
<< /Size {len(objects)+1} /Root {catalog_obj_num} 0 R >>
startxref
{xref_start}
%%EOF
"""

pdf_bytes = (body + "\n".join(xref) + "\n" + trailer).encode("latin-1", "replace")
pdf_b64 = base64.b64encode(pdf_bytes).decode("ascii")

# Markdown file too
md_b64 = base64.b64encode(report_md.encode("utf-8")).decode("ascii")

return [{
  "json": {},
  "binary": {
    "pdf (very ugly)": {
      "data": pdf_b64,
      "fileName": "audit_report.pdf",
      "mimeType": "application/pdf"
    },
    "markdown": {
      "data": md_b64,
      "fileName": "audit_report.md",
      "mimeType": "text/markdown"
    }
  }
}]

